scriptContent:
COLUMN_HEADER_BACKGROUND_COLOR = "#f0eef6"
COLUMN_HEADER_COLOR = "black"
EVEN_ROW_BACKGROUND_COLOR = "#ffffff"
ODD_ROW_BACKGROUND_COLOR = "#ffffff"
EVEN_ROW_TEXT_COLOR = "black"
ODD_ROW_TEXT_COLOR = "black"
FONT_SIZE = "40px"
logo_url="https://www.appviewx.com/wp-content/uploads/2021/08/appviewx-logo.png"

table_html = f""" <!DOCTYPE html>
                    <html>
                    <head>
                        <title>HTML Table Example</title>
                        <style>
                            table
                            {{
                                border-spacing:5px;
                            }}
                            table, th, td
                            {{
                                border:0px solid  #ffffff;
                                border-collapse:collapse;
                            }}
                            th, td
                            {{
                                padding:8px;
                            }}
                            th
                            {{
                                text-align:center;
                                padding:15px;
                            }}
                            tr
                            {{
                                text-align:center;
                                padding:15px;
                                border:1px solid #e6e3ed;
                            }}
                            .even-row
                            {{
                                background-color: {EVEN_ROW_BACKGROUND_COLOR};
                                color:{EVEN_ROW_TEXT_COLOR};
                            }}
                            .odd-row
                            {{
                                background-color: {ODD_ROW_BACKGROUND_COLOR} ;
                                color:{ODD_ROW_TEXT_COLOR};
                            }}
                            table th
                            {{
                                color: {COLUMN_HEADER_COLOR};
                                background-color: {COLUMN_HEADER_BACKGROUND_COLOR};
                            }}
                            h1 {{
                              font-size: {FONT_SIZE};
                            }}
                            img {{
                             display: block;
                              margin-left: auto;
                             margin-right: 0;
                             width:200px;
                             height:auto;
                             }}
                        </style>
                    </head> 
                    <body>
                    <img src={logo_url}/>
                    </body>"""
